### Python

```python
import sys


# 构造长度为 n 的合法排列，若无解返回空列表
def build_permutation(n):
    if n == 2 or n == 4 or n == 6:
        return []

    ans = []

    # 加入一个长度为 8 的合法块，起点为 s
    def add_block8(s):
        ans.extend([s, s + 4, s + 1, s + 5, s + 2, s + 6, s + 3, s + 7])

    # 加入一个长度为 12 的合法块，起点为 s
    def add_block12(s):
        ans.extend([s, s + 4, s + 1, s + 5, s + 2, s + 8,
                    s + 3, s + 9, s + 6, s + 10, s + 7, s + 11])

    if n % 8 == 0:
        s = 1
        while s <= n:
            add_block8(s)
            s += 8

    elif n % 8 == 4:
        s = 1
        # 前面先放若干个 8 块
        while s <= n - 12:
            add_block8(s)
            s += 8
        # 最后放一个 12 块
        add_block12(n - 11)

    elif n % 8 == 2:
        # 先放一个固定的 10 块
        ans.extend([1, 5, 2, 6, 3, 9, 4, 10, 7, 8])
        s = 11
        while s <= n:
            add_block8(s)
            s += 8

    else:  # n % 8 == 6
        # 先放一个固定的 14 块
        ans.extend([1, 5, 2, 6, 3, 7, 4, 12, 8, 14, 9, 13, 10, 11])
        s = 15
        while s <= n:
            add_block8(s)
            s += 8

    return ans


def main():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        ans = build_permutation(n)
        if not ans:
            out.append("-1")
        else:
            out.append(" ".join(map(str, ans)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
```

